package com.p2p.common.social;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.util.*;import javax.net.ssl.*;import java.nio.file.*;
class SocialProtocolTest {
 @Test void framesAreUnicodeAndCoalesced()throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(b);WireCodec.write(out,WireMessage.request("PING",Map.of("text","Chào 🌻")));WireCodec.write(out,WireMessage.event("X",Map.of()));DataInputStream in=new DataInputStream(new ByteArrayInputStream(b.toByteArray()));assertEquals("Chào 🌻",WireCodec.read(in).getPayload().get("text"));assertEquals("EVENT",WireCodec.read(in).getKind());assertNull(WireCodec.read(in));}
 @Test void rejectsBadLengthsAndPartialFrames(){assertThrows(IOException.class,()->WireCodec.read(new DataInputStream(new ByteArrayInputStream(new byte[]{-1,-1,-1,-1}))));assertThrows(EOFException.class,()->WireCodec.read(new DataInputStream(new ByteArrayInputStream(new byte[]{0,0}))));assertThrows(EOFException.class,()->WireCodec.read(new DataInputStream(new ByteArrayInputStream(new byte[]{0,0,0,2,123}))));assertThrows(IOException.class,()->WireCodec.read(new DataInputStream(new ByteArrayInputStream(new byte[]{0,16,0,1}))));}
 @Test void udpRejectsForgeryReflectionAndEnvelopeChanges()throws Exception{byte[] key=new byte[32];new java.security.SecureRandom().nextBytes(key);Map<String,Object> body=Map.of("v",2,"sessionId","s","keyEpoch",1,"seq",1,"ts",System.currentTimeMillis(),"type","UDP_REGISTER");byte[] packet=UdpCodec.sign(body,key,false);assertEquals("s",UdpCodec.verify(packet,key,false).get("sessionId"));assertThrows(IOException.class,()->UdpCodec.verify(packet,key,true));byte[] bad=key.clone();bad[0]^=1;assertThrows(IOException.class,()->UdpCodec.verify(packet,bad,false));Map<String,Object> outer=UdpCodec.outer(packet);outer.put("sessionId","other");assertThrows(IOException.class,()->UdpCodec.verify(Json.MAPPER.writeValueAsBytes(outer),key,false));}
 @Test void tlsDoesNotSilentlyTrustMissingStore(){assertThrows(Exception.class,()->TlsContexts.client(Path.of("does-not-exist.p12"),"password".toCharArray()));}
}
